{
  "application": "report-generation",
  "case_id": "case-smartwatch-marketplace-insights-2026-en",
  "language": "en",
  "report": {
    "type": "market-analysis-report",
    "audience": "e-commerce strategy analyst",
    "tone": "analytical, data-forward, actionable"
  },
  "brief": {
    "title": "Global Smartwatch Secondary Market Analysis — Q1 2026",
    "one_liner": "A comprehensive analysis of 3,600+ secondary-market smartwatch listings across Apple, Garmin, and Samsung to uncover pricing dynamics, geographic arbitrage opportunities, and seller behavior patterns.",
    "goal": "The reader should understand how smartwatch brands retain value on the resale market, identify geographic pricing discrepancies, assess the impact of case size and condition on price, and recognize power-seller pricing strategies — ultimately informing sourcing, pricing, and inventory decisions for secondary-market e-commerce operations."
  },
  "required_sections": [
    {
      "section_id": "market-overview",
      "title": "Market Overview & Listing Composition",
      "objective": "Summarize the overall dataset: total listings, brand distribution, condition mix, and geographic spread. Provide a high-level snapshot of the secondary smartwatch marketplace."
    },
    {
      "section_id": "brand-pricing-analysis",
      "title": "Brand-Level Pricing & Value Retention",
      "objective": "Compare average, median, and price range across Apple, Garmin, and Samsung. Identify which brand commands the highest resale premiums and which shows the widest price variance."
    },
    {
      "section_id": "geospatial-pricing",
      "title": "Geographic Pricing Arbitrage",
      "objective": "Analyze price differences by country for each brand. Highlight regions where specific brands are significantly cheaper or more expensive, identifying potential arbitrage opportunities."
    },
    {
      "section_id": "case-size-premium",
      "title": "Case Size & Price Premium Analysis",
      "objective": "Examine the relationship between Case_Size_mm and listing price. Determine whether larger watch faces command a measurable premium and how this varies by brand."
    },
    {
      "section_id": "seller-behavior",
      "title": "Power Seller Behavior & Pricing Patterns",
      "objective": "Identify high-volume sellers and compare their pricing strategies against low-volume sellers. Assess whether power sellers price higher or lower and whether they favor specific brands or conditions."
    },
    {
      "section_id": "strategic-recommendations",
      "title": "Strategic Recommendations",
      "objective": "Synthesize findings into actionable recommendations for secondary-market operators regarding sourcing regions, brand focus, pricing strategies, and seller partnership opportunities."
    }
  ],
  "kpis": [
    {
      "name": "Median Listing Price by Brand",
      "description": "The median price (USD) of listings for each brand (Apple, Garmin, Samsung), serving as the central measure of resale value."
    },
    {
      "name": "Geographic Price Spread",
      "description": "The difference between the highest and lowest country-level median price for each brand, quantifying arbitrage potential."
    },
    {
      "name": "Case Size Price Correlation",
      "description": "The correlation coefficient between Case_Size_mm and price, measuring how strongly physical size predicts resale value."
    },
    {
      "name": "Power Seller Concentration",
      "description": "The percentage of total listings attributable to the top 5% of sellers by volume, indicating market concentration."
    },
    {
      "name": "New vs. Used Price Premium",
      "description": "The average percentage price premium that 'New' condition listings command over 'Used' listings, by brand."
    }
  ],
  "analysis_dimensions": [
    "brand",
    "condition",
    "Case_Size_mm",
    "Country",
    "price"
  ]
}

